import {buildWorld,T,sites} from './world.mjs';
import {fresh,recover,transition,goal,outcome} from './story.mjs';
const $=id=>document.getElementById(id),SAVE='airegin-nadabi-world-v2',money=n=>'₦'+n.toLocaleString('en-NG');
let state=fresh(),storage=true;try{state=recover(localStorage.getItem(SAVE));}catch{storage=false;}
let w,mode='title',nearest=null,yaw=state.yaw||0,pitch=.43,keys=new Set(),joy={x:0,y:0},runToggle=false,drag=null,jumpVelocity=0,jumpHeight=0,stamina=100,walkPhase=0,moving=false,repairTime=0,chaseTime=0,lastSave=0,lastSecond=-1,lastDistance=-1,lastFoot=0,tick=0,lastFrame=performance.now(),toastUntil=0,sensitivity=1,motion=!matchMedia('(prefers-reduced-motion: reduce)').matches,exploring=false;const forward=new T.Vector3(),right=new T.Vector3(),direction=new T.Vector3(),focus=new T.Vector3(),desired=new T.Vector3(),ray=new T.Raycaster(),tmp=new T.Vector3();
const audio={ctx:null,master:null,muted:false,noise:null,lastBird:0};
function initAudio(){try{if(!audio.ctx){audio.ctx=new (window.AudioContext||window.webkitAudioContext)();audio.master=audio.ctx.createGain();audio.master.gain.value=.32;const compressor=audio.ctx.createDynamicsCompressor();compressor.threshold.value=-8;audio.master.connect(compressor);compressor.connect(audio.ctx.destination);audio.noise=audio.ctx.createBuffer(1,audio.ctx.sampleRate*.15,audio.ctx.sampleRate);const data=audio.noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);}audio.ctx.resume();}catch{}}
function sound(type){if(!audio.ctx||audio.muted)return;const ctx=audio.ctx,now=ctx.currentTime,g=ctx.createGain();g.connect(audio.master);if(type==='step'){const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter();src.buffer=audio.noise;src.playbackRate.value=.85+Math.random()*.3;filter.type='lowpass';filter.frequency.value=350+Math.random()*130;src.connect(filter);filter.connect(g);g.gain.setValueAtTime(.28,now);g.gain.exponentialRampToValueAtTime(.001,now+.12);src.start(now);src.stop(now+.15);src.onended=()=>{src.disconnect();filter.disconnect();g.disconnect();};}else {const o=ctx.createOscillator();o.type=type==='bird'?'sine':'triangle';o.frequency.setValueAtTime(type==='bird'?1800:type==='bad'?150:560,now);o.frequency.exponentialRampToValueAtTime(type==='bird'?2900:type==='bad'?75:900,now+.15);g.gain.setValueAtTime(type==='bird'?.025:type==='bad'?.12:.11,now);g.gain.exponentialRampToValueAtTime(.001,now+.3);o.connect(g);o.start(now);o.stop(now+.32);o.onended=()=>{o.disconnect();g.disconnect();};}}
function save(){if(!w)return;state.position=[w.player.group.position.x,w.player.group.position.z];state.yaw=yaw;try{localStorage.setItem(SAVE,JSON.stringify(state));}catch{storage=false;}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;toastUntil=performance.now()+5600;}
function element(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function clearInput(){keys.clear();joy.x=joy.y=0;drag=null;$('stick').style.transform='translate(0,0)';}
function openDialog(id){clearInput();if(document.pointerLockElement)document.exitPointerLock();mode='dialog';$(id).showModal();$(id).querySelector('button')?.focus();}
function closeDialog(id){$(id).close();mode='playing';$('world').focus({preventScroll:true});}
function setStory(event){const result=transition(state,event);if(result.error){toast(result.error);return false;}state=result.state;save();refreshHUD();sound(event==='steal'?'bad':'good');if(state.record[0])toast(state.record[0]);return true;}
function refreshHUD(){const g=goal(state);$('mission-title').textContent=g.title;$('mission-detail').textContent=g.detail;$('funds').textContent=money(state.funds);$('inventory').textContent=state.fuse?'Replacement fuse in your bag':state.evidence?'Council record copied into your journal':state.repaired?'Feeder repaired. Your decision matters.':'Empty hands. Open possibilities.';w.fuse.visible=!state.repaired&&!state.fuse;for(const [id,node] of labelNodes){node.classList.toggle('goal',id===g.target);}updateLights();}
function updateLights(){for(const l of w.lights){if(l.street){l.material.color.set(state.repaired?'#ffe1a3':'#726c50');continue;}const clinic=l.site==='NADABI CLINIC',council=l.site==='COMMUNITY COUNCIL',market=l.site==='BISI & SONS';let on=false;if(state.repaired){on=!state.decision||(clinic?state.decision!=='council':council?state.decision==='council':market?state.decision!=='care':true);}l.material.opacity=on?.85:.02;}}
function speak(name,role,text,choices){$('person-name').textContent=name;$('person-role').textContent=role;$('person-initial').textContent=name.replace(/^(Dr\. |Chief )/,'')[0];$('dialogue').textContent=text;$('choices').replaceChildren();for(const c of choices){const b=element('button',c.label);if(c.note)b.append(element('small',c.note));b.disabled=Boolean(c.disabled);b.addEventListener('click',()=>{closeDialog('talk');c.run?.();});$('choices').append(b);}openDialog('talk');}
const leave=()=>({label:'I’ll come back.',run:()=>{}});
function interact(){if(mode!=='playing'||!nearest||repairTime>0)return;const id=nearest;if(state.stage==='end'&&exploring){const s=sites[id];speak(s.label,'After the announcement',state.decision==='expose'?'The neighbourhood has power again. Word of what you did is spreading. Dairo has gone quiet. Nobody thinks that will last.':state.decision==='care'?'The clinic and compounds have light. At the market, people are packing up early. Your decision looks different from this side of the street.':'The evening carries on, but people remember whose lights went out.',[{label:'Back to the street.'}]);return;}
 if(id==='teni'){if(state.stage==='meet')speak('Teni','Neighbourhood technician','“The feeder has blown. Bisi has a replacement fuse, but the council won’t release the money. Bring it here. After that, we need to talk about where the power is going.”',[{label:'I’ll find the fuse.',note:'Bisi’s market is across the street. You have '+money(state.funds)+'.',run:()=>setStory('meet')},leave()]);else speak('Teni','Neighbourhood technician',state.repaired?'“The repair is done. Now the difficult part: there isn’t enough for every request. Use the feeder controls. Or find out why that council connection is drawing so much.”':'“Don’t touch the live cabinets. Bring the replacement fuse to the front of the substation. I’ll handle the dangerous work.”',[{label:'Understood.'}]);}
 else if(id==='market'){if(state.stage==='meet'){speak('Bisi','Market association chair','“A fuse? Teni was asking about one earlier. Go and speak to her first. I’m not selling you the wrong part.”',[leave()]);return;}if(state.fuse||state.repaired){speak('Bisi','Market association chair',state.stolen?'“So you think nobody saw you? This is Nadabi. Everybody sees something.”':'“Remember us when you set those controls. Those stalls are somebody’s dinner money.”',[leave()]);return;}const choices=[{label:'Buy the replacement fuse.',note:'Pay ₦1,500. No debt, no favour.',disabled:state.funds<1500,run:()=>setStory('buy')}];if(state.vouched)choices.push({label:'Use Musa’s guarantee.',note:'Keep your money. Owe the market a favour.',run:()=>setStory('borrow')});choices.push({label:'Take the fuse while she looks away.',note:'Keep your money. Risk being caught.',run:()=>{if(setStory('steal')){chaseTime=50;w.guard.group.position.set(11,0,22);sound('bad');}}},leave());speak('Bisi','Market association chair','“Last one. Fifteen hundred. People keep saying ‘for the community’ when they want something free. The community can pay me too.”',choices);}
 else if(id==='station'){if(!state.fuse&&!state.repaired){speak('The feeder','Substation entrance','The replacement slot is empty. You need the fuse from Bisi’s market. Teni has isolated the damaged section.',[{label:'Go and find it.'}]);return;}if(state.repaired){speak('Teni','At the substation','“That’s the repair finished. The feeder controls are on the road side of the yard. Choose the priority, then tell the neighbourhood what you’ve done.”',[{label:'Find the controls.'}]);return;}speak('Teni','At the substation','“Good. That’s the right one. The section is isolated. Fit it here and I’ll reconnect the feeder.”',[{label:'Install the replacement fuse.',note:'Stay beside the substation while the repair finishes.',run:()=>{repairTime=2.6;$('repair-progress').hidden=false;clearInput();}},leave()]);}
 else if(id==='council'){if(state.evidence){speak('The maintenance record','Council noticeboard','You already copied the record: a private council connection draws power outside the public allocation. You have the proof you need.',[{label:'Keep the record safe.'}]);return;}speak('A loose maintenance sheet','Council noticeboard','Under the reception notice, you find a feeder diagram. The council’s private line is marked “temporary”. It has been connected for eleven months.',[{label:'Copy the record.',note:'Evidence unlocks another choice at the feeder controls.',run:()=>setStory('evidence')},{label:'Leave it where it is.'}]);}
 else if(id==='board'){if(!state.repaired){speak('Feeder controls','Substation','The fault lock is still engaged. Nothing can be distributed until the damaged feeder is repaired.',[{label:'Leave the controls.'}]);return;}if(state.decision){speak('Feeder controls','Decision recorded','The priority has been set. The neighbourhood is waiting for you in the square.',[{label:'Go to the community square.'}]);return;}const choices=[{label:'Protect the clinic and compounds.',note:'Keep patients safe and water flowing. The market closes early.',run:()=>setStory('care')},{label:'Keep the council and market online.',note:'Dairo promises you ₦3,000. The clinic loses power.',run:()=>setStory('council')}];if(state.evidence)choices.unshift({label:'Disconnect the council diversion.',note:'Enough power for public needs. Dairo becomes your opponent.',run:()=>setStory('expose')});else choices.push({label:'Investigate before deciding.',note:'Look for maintenance records outside the council hall.',run:()=>toast('The council noticeboard is on the other side of the main junction.')});choices.push(leave());speak('The feeder controls','Your decision','The repaired line still cannot meet all the requests. These switches decide whose evening continues, and whose comes to a stop.',choices);}
 else if(id==='clinic'){const choices=[];if(!state.promised)choices.push({label:'Promise to protect the clinic.',note:'Dr. Sade will remember whether you keep your word.',run:()=>setStory('promise')});choices.push({label:'I need to see what I can do.'});speak('Dr. Sade','Clinic operator','“There are vaccines in that fridge. People can argue about fairness tomorrow. Tonight, keep this place running. Please.”',choices);}
 else if(id==='musa'){const choices=[];if(!state.vouched)choices.push({label:'Ask him to guarantee the fuse.',note:'Bisi trusts Musa. Borrowing creates an obligation.',run:()=>setStory('vouch')});if(!state.donation)choices.push({label:'Accept the residents’ contribution.',note:'Add ₦500 to the repair fund.',run:()=>setStory('donate')});choices.push(leave());speak('Musa','Residents’ organiser','“We can’t fix everything tonight. But we can decide what sort of people we want to be when things go wrong. Tell me what you need.”',choices);}
 else if(id==='square'){if(state.stage!=='announce'){speak('The community square','People are gathering','People are waiting for an answer. First repair the feeder and set its priority at the controls.',[{label:'There is still work to do.'}]);return;}speak('Your neighbours','The moment becomes public','The conversations stop as you step forward. You can still walk away. Or tell everyone what you chose, and why.',[{label:'Make the announcement.',note:'End the evening and see who stands with you.',run:()=>{if(setStory('announce'))finish();}},{label:'Not yet.'}]);}}
function finish(){mode='ending';clearInput();save();const o=outcome(state);$('hud').hidden=true;$('ending').hidden=false;$('ending-title').textContent=o.title;$('ending-summary').textContent=o.summary;$('ending-consequences').replaceChildren(element('p','Public trust: '+o.trust+' / 10'),...o.consequences.map(t=>element('p',t)));$('labels').hidden=true;$('replay').focus();sound('good');}
function start(newGame=false){if(newGame){state=fresh();yaw=0;chaseTime=0;jumpHeight=0;jumpVelocity=0;stamina=100;exploring=false;w.guard.group.position.set(13,0,-12);}state.started=true;w.player.group.position.set(state.position[0],.1,state.position[1]);if(blocked(state.position[0],state.position[1])){w.player.group.position.set(0,.1,31);}cameraSnap();$('title-screen').hidden=true;$('ending').hidden=true;$('hud').hidden=false;$('labels').hidden=false;mode='playing';clearInput();initAudio();save();refreshHUD();if(state.stage==='end'){finish();return;}else toast(storage?'Welcome to Nadabi. Move through the street and approach people to talk.':'Progress cannot save here, but you can play this evening normally.');$('world').focus({preventScroll:true});}
function pause(){if(mode!=='playing')return;save();openDialog('pause-menu');}
function blocked(x,z){if(x<-62||x>62||z<-68||z>68)return true;return w.colliders.some(c=>Math.abs(x-c.x)<c.w/2+.38&&Math.abs(z-c.z)<c.d/2+.38);}
function move(body,dx,dz){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.18));for(let i=0;i<steps;i++){if(!blocked(body.position.x+dx/steps,body.position.z))body.position.x+=dx/steps;if(!blocked(body.position.x,body.position.z+dz/steps))body.position.z+=dz/steps;}}
function cameraSnap(){focus.copy(w.player.group.position).add(new T.Vector3(0,1.35,0));desired.set(focus.x+Math.sin(yaw)*8,focus.y+4.4,focus.z+Math.cos(yaw)*8);w.camera.position.copy(desired);w.camera.lookAt(focus);}
const labelNodes=new Map();
function buildLabels(){for(const [id,s] of Object.entries(sites)){const node=element('div',undefined,'world-label');node.append(element('span',undefined,'diamond'),element('strong',s.label));$('labels').append(node);labelNodes.set(id,node);}}
function labels(){const g=goal(state),pos=w.player.group.position;for(const [id,node] of labelNodes){const p=sites[id],dist=Math.hypot(p.x-pos.x,p.z-pos.z);tmp.set(p.x,3,p.z).project(w.camera);const show=mode==='playing'&&tmp.z<1&&tmp.z>0&&Math.abs(tmp.x)<1.2&&Math.abs(tmp.y)<1.2&&(dist<25||id===g.target);node.hidden=!show;if(show)node.style.transform=`translate(${(tmp.x*.5+.5)*innerWidth}px,${(-tmp.y*.5+.5)*innerHeight}px) translate(-50%,-100%)`;}}
function updateNearest(){let next=null,min=3.35;for(const [id,p] of Object.entries(sites)){const distance=Math.hypot(p.x-w.player.group.position.x,p.z-w.player.group.position.z);if(distance<min){min=distance;next=id;}}if(next!==nearest){nearest=next;$('interaction').hidden=!next||repairTime>0;if(next){$('interact-label').textContent=next==='station'?'Inspect substation':next==='board'?'Use feeder controls':next==='council'?'Read council noticeboard':next==='square'?'Address the neighbourhood':'Talk to '+(next==='market'?'Bisi':next==='clinic'?'Dr. Sade':sites[next].label);}}const target=sites[goal(state).target],d=Math.round(Math.hypot(target.x-w.player.group.position.x,target.z-w.player.group.position.z));if(d!==lastDistance){$('distance').textContent=d+' m away';lastDistance=d;}}
function animatePerson(person,speed,dt,t){const swing=speed>.1?Math.sin(t*9)*Math.min(.65,speed*.15):Math.sin(t*1.4+person.phase)*.025;person.limbs[0].rotation.x=swing;person.limbs[2].rotation.x=-swing;person.limbs[1].rotation.x=-swing*.75;person.limbs[3].rotation.x=swing*.75;person.body.rotation.z=Math.sin(t*3+person.phase)*.012;}
function movement(dt,t){const a={x:0,z:0,sprint:runToggle||keys.has('sprint')};if(keys.has('left'))a.x--;if(keys.has('right'))a.x++;if(keys.has('forward'))a.z--;if(keys.has('back'))a.z++;a.x+=joy.x;a.z+=joy.y;const mag=Math.min(1,Math.hypot(a.x,a.z));direction.set(a.x,0,a.z);if(direction.length()>1)direction.normalize();forward.set(-Math.sin(yaw),0,-Math.cos(yaw));right.set(Math.cos(yaw),0,-Math.sin(yaw));const dx=right.x*direction.x+forward.x*-direction.z,dz=right.z*direction.x+forward.z*-direction.z;const running=a.sprint&&stamina>2&&mag>.1,speed=running?6.6:3.8;if(running)stamina=Math.max(0,stamina-dt*23);else stamina=Math.min(100,stamina+dt*15);if(repairTime<=0){move(w.player.group,dx*speed*dt,dz*speed*dt);moving=mag>.08;if(moving){const angle=Math.atan2(dx,dz),old=w.player.group.rotation.y;w.player.group.rotation.y=old+Math.atan2(Math.sin(angle-old),Math.cos(angle-old))*(1-Math.exp(-15*dt));walkPhase+=dt*(running?1.4:1);if(t-lastFoot>(running?.24:.37)&&jumpHeight<.04){sound('step');lastFoot=t;}}}else moving=false;if(jumpHeight>0||jumpVelocity>0){jumpVelocity-=17*dt;jumpHeight=Math.max(0,jumpHeight+jumpVelocity*dt);if(jumpHeight===0)jumpVelocity=0;}w.player.group.position.y=.12+jumpHeight+(moving&&motion?Math.sin(walkPhase*18)*.035:0);animatePerson(w.player,moving?speed:0,dt,walkPhase);$('stamina-fill').style.transform=`scaleX(${stamina/100})`;}
function updateNPCs(dt,t){for(const p of w.people){if(p.speed){p.group.position.z+=p.speed*p.direction*dt;if(p.group.position.z>59)p.direction=-1;if(p.group.position.z<-59)p.direction=1;p.group.rotation.y=p.direction>0?0:Math.PI;}animatePerson(p,p.speed||0,dt,t);}for(const a of Object.values(w.actors))animatePerson(a,0,dt,t);for(const v of w.vehicles){v.group.position.z+=v.speed*dt;if(v.group.position.z>68)v.group.position.z=-68;}
 if(chaseTime>0&&state.stolen&&!state.repaired){chaseTime-=dt;const g=w.guard.group,pos=w.player.group.position,dx=pos.x-g.position.x,dz=pos.z-g.position.z,d=Math.hypot(dx,dz);if(d>1){move(g,dx/d*4.2*dt,dz/d*4.2*dt);g.rotation.y=Math.atan2(dx,dz);}animatePerson(w.guard,4.2,dt,t);$('chase').hidden=false;if(d<1.2){chaseTime=0;setStory('caught');toast('The guard recovered the fuse. You still have your money. Return to Bisi.');sound('bad');}}else {$('chase').hidden=true;animatePerson(w.guard,0,dt,t);}}
function updateCamera(dt,t){focus.copy(w.player.group.position);focus.y+=1.35;const radius=8.2,dy=Math.sin(pitch)*radius;desired.set(focus.x+Math.sin(yaw)*Math.cos(pitch)*radius,focus.y+dy,focus.z+Math.cos(yaw)*Math.cos(pitch)*radius);const diff=tmp.copy(desired).sub(focus),len=diff.length();ray.set(focus,diff.normalize());ray.far=len;const hits=ray.intersectObjects(w.occluders,false);if(hits.length&&hits[0].distance<len)desired.copy(focus).addScaledVector(diff,Math.max(1.1,hits[0].distance-.45));w.camera.position.lerp(desired,1-Math.exp(-10*dt));w.camera.lookAt(focus);}
function drawMap(){const c=$('map'),g=c.getContext('2d'),size=220,scale=1.45,cx=110,cy=110;g.fillStyle='#283c30';g.fillRect(0,0,size,size);g.fillStyle='#5e6d57';g.fillRect(cx-10,10,20,200);g.fillRect(20,cy-10,180,20);g.fillStyle='#897e5e';for(const c of w.colliders){if(c.w>30||c.d>30)continue;g.fillRect(cx+c.x*scale-c.w*scale/2,cy+c.z*scale-c.d*scale/2,c.w*scale,c.d*scale);}const target=goal(state).target;for(const [id,p] of Object.entries(sites)){g.beginPath();g.arc(cx+p.x*scale,cy+p.z*scale,id===target?5:2.5,0,Math.PI*2);g.fillStyle=id===target?'#c4e9a0':'#e4c18d';g.fill();}const pos=w.player.group.position;g.save();g.translate(cx+pos.x*scale,cy+pos.z*scale);g.rotate(-yaw);g.fillStyle='#ffffff';g.beginPath();g.moveTo(0,-7);g.lineTo(5,5);g.lineTo(0,2);g.lineTo(-5,5);g.closePath();g.fill();g.restore();g.fillStyle='#f0eadc';g.font='bold 12px Arial';g.fillText('N',106,16);}
function frame(){const now=performance.now(),dt=Math.min(.25,Math.max(0,(now-lastFrame)/1000)),t=now/1000;lastFrame=now;tick++;if(mode==='playing'){movement(dt,t);updateNPCs(dt,t);updateCamera(dt,t);updateNearest();if(!exploring&&state.stage!=='end'){state.seconds=Math.max(0,state.seconds-dt);if(state.seconds===0){setStory('timeout');finish();}}if(repairTime>0){repairTime-=dt;$('repair-fill').style.transform=`scaleX(${Math.min(1,1-repairTime/2.6)})`;$('interaction').hidden=true;if(repairTime<=0){$('repair-progress').hidden=true;setStory('repair');chaseTime=0;nearest=null;}}const seconds=Math.ceil(state.seconds);if(seconds!==lastSecond){lastSecond=seconds;const worldMinutes=17*60+20+(480-state.seconds)/12;$('clock').textContent=String(Math.floor(worldMinutes/60)).padStart(2,'0')+':'+String(Math.floor(worldMinutes%60)).padStart(2,'0');$('map-status').textContent=Math.ceil(state.seconds/60)+' min to dusk';$('compass-heading').textContent=['N','NW','W','SW','S','SE','E','NE'][(Math.round(((yaw%(Math.PI*2)+Math.PI*2)%(Math.PI*2))/(Math.PI/4)))%8];}if(now-lastSave>4000){save();lastSave=now;}if(t-audio.lastBird>9){audio.lastBird=t;sound('bird');}if(tick%6===0)drawMap();labels();}
 else if(mode==='title'){const p=w.player.group.position;w.camera.position.set(p.x+Math.sin(t*.035+.55)*15,8.5,p.z+Math.cos(t*.035+.55)*15);w.camera.lookAt(p.x-2,1.5,p.z-9);updateNPCs(dt,t);}
 if(!$('toast').hidden&&now>toastUntil)$('toast').hidden=true;const dusk=1-state.seconds/480;w.sun.intensity=3.2-dusk*.65;w.renderer.render(w.scene,w.camera);if(tick%6===0){$('world').dataset.position=`${w.player.group.position.x.toFixed(2)},${w.player.group.position.z.toFixed(2)}`;$('world').dataset.stage=state.stage;$('world').dataset.drawcalls=String(w.renderer.info.render.calls);}}
const mapping={KeyW:'forward',ArrowUp:'forward',KeyS:'back',ArrowDown:'back',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',ShiftLeft:'sprint',ShiftRight:'sprint'};
function jump(){if(mode==='playing'&&jumpHeight===0&&repairTime<=0){jumpVelocity=5.4;sound('step');}}
addEventListener('keydown',e=>{if(e.code==='Escape'){if(mode==='playing'){e.preventDefault();pause();}return;}if(mode!=='playing')return;if(mapping[e.code]){e.preventDefault();keys.add(mapping[e.code]);}if(!e.repeat&&e.code==='KeyE'){e.preventDefault();interact();}if(!e.repeat&&e.code==='Space'){e.preventDefault();jump();}});addEventListener('keyup',e=>{if(mapping[e.code])keys.delete(mapping[e.code]);});addEventListener('blur',()=>{clearInput();if(mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(mode==='playing')pause();}});addEventListener('pagehide',save);
$('world').addEventListener('pointerdown',e=>{if(mode!=='playing')return;if(e.pointerType==='touch'&&e.clientX<innerWidth*.35)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};$('world').setPointerCapture(e.pointerId);});$('world').addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||mode!=='playing')return;yaw-=(e.clientX-drag.x)*.005*sensitivity;pitch=Math.max(.15,Math.min(1.05,pitch+(e.clientY-drag.y)*.003*sensitivity));drag.x=e.clientX;drag.y=e.clientY;});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('world').addEventListener(event,()=>{drag=null;});
let stickPointer=null;const stick=$('joystick');stick.addEventListener('pointerdown',e=>{if(stickPointer!==null)return;stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e);});function stickMove(e){if(e.pointerId!==stickPointer)return;const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,dist=Math.hypot(dx,dy),limit=r.width*.33,gain=dist>limit?limit/dist:1;joy.x=dx*gain/limit;joy.y=dy*gain/limit;if(Math.hypot(joy.x,joy.y)<.12)joy={x:0,y:0};$('stick').style.transform=`translate(${dx*gain}px,${dy*gain}px)`;}stick.addEventListener('pointermove',stickMove);for(const event of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(event,()=>{stickPointer=null;joy={x:0,y:0};$('stick').style.transform='translate(0,0)';});
$('sprint').addEventListener('click',()=>{runToggle=!runToggle;$('sprint').setAttribute('aria-pressed',String(runToggle));});$('jump').addEventListener('pointerdown',jump);$('interact').addEventListener('click',interact);$('begin').addEventListener('click',()=>start());$('new-game').addEventListener('click',()=>openDialog('restart-confirm'));$('pause').addEventListener('click',pause);$('resume').addEventListener('click',()=>closeDialog('pause-menu'));$('talk-close').addEventListener('click',()=>closeDialog('talk'));$('controls-open').addEventListener('click',()=>{$('pause-menu').close();openDialog('settings');});$('settings-close').addEventListener('click',()=>{$('settings').close();openDialog('pause-menu');});$('journal-open').addEventListener('click',()=>{$('journal-list').replaceChildren(...(state.record.length?state.record:['You have just arrived. Speak to Teni to find out what happened.']).map(t=>element('li',t)));openDialog('journal');});$('journal-close').addEventListener('click',()=>closeDialog('journal'));$('restart').addEventListener('click',()=>{$('pause-menu').close();openDialog('restart-confirm');});$('replay').addEventListener('click',()=>openDialog('restart-confirm'));$('restart-cancel').addEventListener('click',()=>{$('restart-confirm').close();if(!state.started){mode='title';return;}if(state.stage==='end'&&!exploring){finish();return;}mode='playing';});$('restart-confirmed').addEventListener('click',()=>{$('restart-confirm').close();start(true);});$('explore').addEventListener('click',()=>{$('ending').hidden=true;$('hud').hidden=false;$('labels').hidden=false;mode='playing';exploring=true;$('mission-title').textContent='Stay a little longer';$('mission-detail').textContent='Walk the street and hear what your neighbours think.';$('world').focus();});
$('audio').addEventListener('click',()=>{initAudio();audio.muted=!audio.muted;if(audio.master)audio.master.gain.value=audio.muted?0:.32;$('audio').textContent=audio.muted?'Sound off':'Sound on';$('audio').setAttribute('aria-label',audio.muted?'Turn sound on':'Turn sound off');});$('sensitivity').addEventListener('input',e=>{sensitivity=Number(e.target.value);});$('quality').addEventListener('change',e=>{w.renderer.shadowMap.enabled=e.target.checked;w.scene.traverse(o=>{if(o.material)o.material.needsUpdate=true;});});$('motion').checked=motion;$('motion').addEventListener('change',e=>{motion=e.target.checked;});
for(const id of ['talk','pause-menu','settings','journal','restart-confirm'])$(id).addEventListener('cancel',e=>{e.preventDefault();if(id==='settings'){$(id).close();openDialog('pause-menu');}else if(id==='restart-confirm')$('restart-cancel').click();else closeDialog(id);});
try{w=buildWorld($('world'));buildLabels();w.player.group.position.set(state.position[0],.12,state.position[1]);cameraSnap();refreshHUD();$('begin').disabled=false;$('begin').textContent=state.started?'Continue your evening ↗':'Enter Nadabi ↗';$('new-game').hidden=!state.started;w.renderer.setAnimationLoop(frame);}catch(error){$('title-screen').hidden=true;$('error').hidden=false;$('error-message').textContent='This 3D world could not start. Enable WebGL or try an up-to-date browser. '+(error.message||'');console.error(error);}
